<?php require 'config.php';$msg='';if($_SERVER['REQUEST_METHOD']=='POST'){$n=trim($_POST['name']);$e=trim($_POST['email']);$p=password_hash($_POST['password'],PASSWORD_DEFAULT);$ph=trim($_POST['phone']);$st=$conn->prepare("INSERT INTO users(name,email,password,phone) VALUES(?,?,?,?)");$st->bind_param("ssss",$n,$e,$p,$ph);if($st->execute()){header('Location: login.php');exit;} $msg='Email already registered.';}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="formpage"><div class="panel"><h1>Create Account</h1><?php if($msg):?><p class="error"><?=$msg?></p><?php endif;?><form method="post"><input name="name" placeholder="Full name" required><input name="email" type="email" placeholder="Email" required><input name="phone" placeholder="Phone"><input name="password" type="password" placeholder="Password" required><button class="btn">Register</button></form><p>Already registered? <a href="login.php">Login</a></p></div></main></body></html>